with filtered as (select *, coalesce(channel, 'Unknown') as channel_filled, datediff(current_date(), starts_on) as days_since_starts_on, coalesce(channel, 'DIRECT') as channel_clean from promotions where promo_code not in ('VIP', 'SPRING10', 'BUNDLE')) select id, channel, promo_code, starts_on, channel_clean, percent_rank() over (order by days_since_starts_on desc nulls last) as days_since_starts_on_percent_rank, cume_dist() over (partition by channel, promo_code order by days_since_starts_on desc nulls first) as days_since_starts_on_cume_dist from filtered where promo_code = 'WELCOME5';
